// CarPlay map-button glyphs — OUR artwork, not SF Symbols.
//
// WHY DATA URIs (and why this is OTA-able on an existing binary):
// CPMapButton only takes a UIImage, and react-native-carplay builds it with
// [RCTConvert UIImage:] (RCTConvert+RNCarPlay.m). Our own code comments used to
// claim custom images simply cannot work under bridgeless — that is WRONG, and
// it cost us the SF-Symbol detour. RCTConvert.mm:1339 has a dedicated `data:`
// branch that decodes inline via [UIImage imageWithData:] with NO bridge and NO
// image loader, and resolveAssetSource.js:112 returns {uri} objects untouched,
// so a data URI survives our patched parseConfig/traverse verbatim. The whole
// chain is JS + stock RN native code that already ships in build 67 — no native
// patch, no new build.
//
// It also dodges the OTA asset path-key trap (see the ota-asset-path-key-trap
// note): expo-updates dedupes embedded assets by PATH, so editing a require()'d
// PNG's CONTENT via OTA silently serves the OLD embedded copy. These bytes live
// in the JS bundle itself, so changing a glyph always takes effect.
//
// SIZING: RCTImageSource.m:73 reads `scale` off the dict, so 132px art at
// scale 3 lands as a crisp 44pt button glyph.
//
// focusedImage IS SUPPLIED DELIBERATELY: CarPlay flattens the focused state to a
// solid system-focus-colour silhouette when focusedImage is nil (CPMapButton.h:51-52
// documents the alpha-derived behaviour). Passing our own art keeps the real
// glyph while a rotary-controller head unit has it focused.
//
// Source art: assets/images/police.png + assets/images/scout-mic.png — the SAME
// files the phone HUD uses (src/components/MapControlIcons.tsx, and the Scout mic
// button below), which is the standing "CarPlay matches the phone" rule.
// Regenerate: sips -Z 132 <src>.png, then base64.

type CarIcon = { uri: string; width: number; height: number; scale: number };

const icon = (b64: string): CarIcon => ({
  uri: 'data:image/png;base64,' + b64,
  width: 44,
  height: 44,
  scale: 3,
});

export const CAR_ICON_POLICE: CarIcon = icon(
  '',
);

export const CAR_ICON_MIC: CarIcon = icon(
  '',
);

// A fully TRANSPARENT glyph, used only as a layout spacer. CarPlay BOTTOM-anchors
// the map-button column, so the only way to lift the real buttons out of the
// bottom-right (where our maneuver banner lives) is to occupy the lower slots.
// `hidden: true` does NOT work — verified in the sim, the buttons still drew — so
// the spacer is an invisible, DISABLED button instead.
export const CAR_ICON_BLANK: CarIcon = icon(
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==',
);

